// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency, uint256 amount, uint256 unlockTime, bool assetBurnable) public {
        // The only way DAO can change is via setDAO(). In this test we never call setDAO except in constructor.
        // So after any call to assertGovernanceApproved, DAO must still be address(this).
        vm.assume(sender != address(0));
        vm.assume(target != address(0));

        // We need to set up flash governance config so the function doesn't revert before reading DAO
        // Actually, assertGovernanceApproved doesn't read DAO directly, but we should still test
        // The bug is that setDAO() doesn't update DAO but still deletes governer.
        // For the test, we just call assertGovernanceApproved (will likely revert but that's ok).

        // To make the call potentially succeed, set flashGovernanceConfig.asset to an ERC20 that will transferFrom
        // For simplicity just let it revert - we check post-state

        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency));

        // After any call, DAO must remain the constructor address (this) unless a successful proposal changed it
        // We never call setDAO, so it must remain address(this)
        assertTrue(c.DAO() == address(this), "DAO changed unexpectedly");
    }
}

